import pytest

from bedrock_protocol import v1001, v2168, v2225

Action = v2225.PositionTrackingDBServerBroadcastPacket.Action

# generated by gophertunnel b8bd735:
# packet.PositionTrackingDBServerBroadcast{
# BroadcastAction: packet.PositionTrackingDBBroadcastActionUpdate, TrackingID: 7,
# Payload: map[string]any{"id": "00000007"}}
UPDATE = bytes.fromhex("000e0a000802696408303030303030303700")

# generated by gophertunnel b8bd735:
# packet.PositionTrackingDBServerBroadcast{
# BroadcastAction: packet.PositionTrackingDBBroadcastActionNotFound,
# TrackingID: -1, Payload: map[string]any{}}
NOT_FOUND = bytes.fromhex("02010a0000")

# generated by gophertunnel b8bd735:
# packet.PositionTrackingDBServerBroadcast{
# BroadcastAction: packet.PositionTrackingDBBroadcastActionDestroy,
# TrackingID: 300, Payload: map[string]any{}}
WIDE = bytes.fromhex("01d8040a0000")

GOLDENS = [
    pytest.param(
        v2225.PositionTrackingDBServerBroadcastPacket(
            action=Action.UPDATE,
            id=v2225.PositionTrackingId(raw_id=7),
            data=v2225.nbt.CompoundTag({"id": v2225.nbt.StringTag("00000007")}),
        ),
        UPDATE,
        id="update",
    ),
    pytest.param(
        v2225.PositionTrackingDBServerBroadcastPacket(
            action=Action.NOT_FOUND,
            id=v2225.PositionTrackingId(raw_id=-1),
            data=v2225.nbt.CompoundTag(),
        ),
        NOT_FOUND,
        id="not-found",
    ),
    pytest.param(
        v2225.PositionTrackingDBServerBroadcastPacket(
            action=Action.DESTROY,
            id=v2225.PositionTrackingId(raw_id=300),
            data=v2225.nbt.CompoundTag(),
        ),
        WIDE,
        id="wide-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_position_tracking_db_server_broadcast_is_packet_153(version):
    assert version.PACKETS[153] is version.PositionTrackingDBServerBroadcastPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_position_tracking_db_server_broadcast_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_position_tracking_db_server_broadcast_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
